% Given data
t = [0 1 2 3 4];
k = [0.10 0.25 0.35 0.40 0.42];

% Composite Simpson's 1/3 integration
dt = t(2) - t(1);
I = dt/3 * (k(1) + 4*k(2) + 2*k(3) ...
    + 4*k(4) + k(5));

figure; %[output:27916ec8]
hold on; %[output:27916ec8]

% Plot the two quadratic regions

for i = 1:2:3

    % Fit quadratic through three points
    p = polyfit(t(i:i+2), k(i:i+2), 2);

    % Generate smooth curve
    x = linspace(t(i), t(i+2), 100);
    y = polyval(p, x);

    % Shade area under quadratic curve
    patch([x fliplr(x)], ... %[output:27916ec8]
        [zeros(size(x)) fliplr(y)], ... %[output:27916ec8]
        [0.65 0.82 1.0], ... %[output:27916ec8]
        'FaceAlpha', 0.4, ... %[output:27916ec8]
        'EdgeColor', 'k', ... %[output:27916ec8]
        'LineWidth', 0.8, ... %[output:27916ec8]
        'HandleVisibility', 'off'); %[output:27916ec8]

    % Plot quadratic approximation
    if i == 1
        plot(x, y, 'b-', ...
            'LineWidth', 2, ...
            'DisplayName', 'Quadratic interpolation');
    else
        plot(x, y, 'b-', ...
            'LineWidth', 2, ...
            'HandleVisibility', 'off');
    end
    
end

% Plot given data points
plot(t, k, 'ro', ... %[output:27916ec8]
    'MarkerFaceColor', 'r', ... %[output:27916ec8]
    'MarkerSize', 7, ... %[output:27916ec8]
    'DisplayName', 'Given data'); %[output:27916ec8]

% Formatting
xlabel(' t (s)', 'FontSize', 12); %[output:27916ec8]
ylabel(' k (W/(m K))', ... %[output:27916ec8]
    'FontSize', 12); %[output:27916ec8]

title(sprintf('Composite Simpson''s 1/3 Rule (I = %.4f)', I)); %[output:27916ec8]

legend('Location', 'southeast'); %[output:27916ec8]
grid on; %[output:27916ec8]
box on; %[output:27916ec8]

xlim([0 4]); %[output:27916ec8]
ylim([0 0.5]); %[output:27916ec8]
xticks(0:1:4); %[output:27916ec8]

set(gca, 'FontSize', 11); %[output:27916ec8]
hold off; %[output:27916ec8]

% Display integral
fprintf('Simpson integral = %.5f\n', I); %[output:5803b568]

% Export for Overleaf (run after figure displays)
exportgraphics(gcf, 'simpson_rule.pdf', ... %[output:group:42ab8c88] %[output:27916ec8]
     'ContentType', 'vector'); %[output:group:42ab8c88] %[output:27916ec8]

